mapper.update:
update sign_word
set view_count = view_count + 1
where sign_word_name = #{signWordName}

mapper.select:
SELECT sign_word_id as signWordId, sign_word_name as signWordName, description FROM sign_word
WHERE sign_word_name LIKE CONCAT('%', #{keyword}, '%')
ORDER BY sign_word_id DESC LIMIT #{offset}, #{pageSize}
